import sys
import os
import tty
import termios
import select
import re

class Node:
    def __init__(self, name, parent=None, depth=0):
        self.name = name
        self.parent = parent
        self.depth = depth
        self.samples = 0
        self.children_list = []
        self.children_dict = {}

    def add_stack(self, stack, count):
        self.samples += count
        if not stack:
            return
        part = stack[0]
        if part not in self.children_dict:
            child = Node(part, self, self.depth + 1)
            self.children_dict[part] = child
            self.children_list.append(child)
        self.children_dict[part].add_stack(stack[1:], count)

def sort_tree(node):
    node.children_list.sort(key=lambda x: (-x.samples, x.name))
    for child in node.children_list:
        sort_tree(child)

def get_color(name, is_selected, is_matched, is_parent):
    if is_selected:
        return (10, 10, 10), (250, 250, 250)

    if name == "all":
        r, g, b = 205, 3, 0
    else:
        h = 0
        for c in name:
            h = (h * 53 + ord(c)) & 0xFFFFFFFF
        g = h % 200
        r = 205 + g // 5
        b = g // 4

    if is_matched:
        return (225, 10, 10), (10, 35, 150)

    bg = (r, g, b)
    if is_parent:
        bg = (int(bg[0] / 2.5), int(bg[1] / 2.5), int(bg[2] / 2.5))

    lum = 0.2126 * bg[0] + 0.7152 * bg[1] + 0.0722 * bg[2]
    fg = (10, 10, 10) if lum > 120 else (225, 225, 225)
    return fg, bg

def format_color(fg, bg):
    return f"\x1b[38;2;{fg[0]};{fg[1]};{fg[2]}m\x1b[48;2;{bg[0]};{bg[1]};{bg[2]}m"

def strip_ansi(text):
    return re.sub(r'\x1b\[[0-9;]*[mG]', '', text)

class App:
    def __init__(self, root, args, input_data):
        self.root = root
        self.args = args
        self.input_data = input_data
        self.zoom_node = root
        self.selected_node = root
        self.scroll_depth = 0
        self.search_query = ""
        self.matches = []
        self.match_idx = -1
        self.width = 80
        self.height = 24

    def get_layout(self, zoom_node, target_depth, width):
        if target_depth < zoom_node.depth:
            curr = zoom_node
            while curr.depth > target_depth:
                curr = curr.parent
            return [(curr, 0, width)]

        layout = []
        def recurse(curr, current_x, current_w):
            if curr.depth == target_depth:
                layout.append((curr, current_x, current_w))
                return

            x = current_x
            for child in curr.children_list:
                child_w = (child.samples / zoom_node.samples) * width
                if child_w > 0:
                    recurse(child, x, child_w)
                x += child_w

        recurse(zoom_node, 0, width)
        return layout

    def run(self):
        self.fd = sys.stdin.fileno()
        self.old_settings = termios.tcgetattr(self.fd)
        try:
            tty.setraw(self.fd)
            sys.stdout.write("\x1b[?25l")
            sys.stdout.flush()
            while True:
                self.update_size()
                self.render()
                if not self.handle_input():
                    break
        finally:
            termios.tcsetattr(self.fd, termios.TCSADRAIN, self.old_settings)
            sys.stdout.write("\x1b[?25h\x1b[0m")
            sys.stdout.flush()
            if self.args.echo:
                for line in self.input_data:
                    sys.stdout.write(line)

    def update_size(self):
        try:
            size = os.get_terminal_size()
            self.width = size.columns
            self.height = size.lines
        except:
            pass

    def render(self):
        buf = []
        buf.append("\x1b[H\x1b[J")

        header_rendered = f" \x1b[1m\x1b[38;5;3m[Flamegraph]\x1b[0m | \x1b[1mTop\x1b[0m                  \x1b[1m{self.args.filename or 'stdin'}\x1b[0m                \x1b[1mflamelens v0.3.1\x1b[0m"
        buf.append("─" * self.width + "\r\n")
        buf.append(header_rendered + " " * (self.width - len(strip_ansi(header_rendered))) + "\r\n")
        buf.append("─" * self.width + "\r\n")

        fg_rows = self.height - 7
        for i in range(fg_rows):
            depth = self.scroll_depth + i
            layout = self.get_layout(self.zoom_node, depth, self.width)

            rendered_line = ""
            current_pos = 0
            for node, x, w in layout:
                start = int(round(x))
                end = int(round(x + w))
                if end > self.width: end = self.width
                if end <= start: continue

                if start > current_pos:
                    rendered_line += "\x1b[0m" + " " * (start - current_pos)

                is_selected = (node == self.selected_node)
                is_matched = self.is_node_matched(node)
                is_parent = (depth < self.zoom_node.depth)
                fg, bg = get_color(node.name, is_selected, is_matched, is_parent)

                node_width = end - start
                cell_text = " " * node_width
                if node_width > 1:
                    label_text = node.name[:node_width-2]
                    cell_text = " " + label_text + " " * (node_width - 1 - len(label_text))
                elif node_width == 1:
                    cell_text = "."

                rendered_line += format_color(fg, bg) + cell_text
                current_pos = end

            if current_pos < self.width:
                rendered_line += "\x1b[0m" + " " * (self.width - current_pos)

            buf.append(rendered_line + "\r\n")

        buf.append("\x1b[" + str(self.height - 3) + ";1H")
        info_title = "Match" if self.search_query and not self.is_node_matched(self.selected_node) else "Selected"
        title_rendered = f"\x1b[1m\x1b[38;5;3m{info_title} \x1b[0m"
        sep = "─" * (self.width - len(info_title) - 1)
        buf.append(title_rendered + sep + "\r\n")

        if info_title == "Match":
            total_match_samples = sum(m.samples for m in self.matches)
            percent = (total_match_samples / self.root.samples) * 100
            buf.append(f'"{self.search_query}" [{total_match_samples} samples, {percent:.2f}% of all]\r\n')
        else:
            n = self.selected_node
            percent_all = (n.samples / self.root.samples) * 100
            if self.zoom_node != self.root:
                percent_zoom = (n.samples / self.zoom_node.samples) * 100
                buf.append(f"{n.name} [{n.samples} samples, {percent_all:.2f}% of all, {percent_zoom:.2f}% of zoomed]\r\n")
            else:
                buf.append(f"{n.name} [{n.samples} samples, {percent_all:.2f}% of all]\r\n")

        buf.append("─" * self.width + "\r\n")
        help_rendered = " [\x1b[1m\x1b[38;5;3mhjkl\x1b[0m: move cursor] [\x1b[1m\x1b[38;5;3mf/b\x1b[0m: scroll] [\x1b[1m\x1b[38;5;3menter/esc\x1b[0m: zoom] [\x1b[1m\x1b[38;5;3m/\x1b[0m: search] [\x1b[1m\x1b[38;5;3m#\x1b[0m: search like"
        buf.append(help_rendered + " " * (self.width - len(strip_ansi(help_rendered))))

        sys.stdout.write("".join(buf))
        sys.stdout.flush()

    def is_node_matched(self, node):
        if not self.search_query: return False
        try: return re.search(self.search_query, node.name) is not None
        except: return False

    def update_matches(self):
        self.matches = []
        if not self.search_query: return
        def recurse(node):
            if self.is_node_matched(node): self.matches.append(node)
            for child in node.children_list: recurse(child)
        recurse(self.root)
        self.match_idx = -1

    def handle_input(self):
        r, _, _ = select.select([sys.stdin], [], [], 0.1)
        if not r: return True
        key = sys.stdin.read(1)
        if key == '\x1b':
            # Handle escape sequences
            r, _, _ = select.select([sys.stdin], [], [], 0)
            if r:
                next1 = sys.stdin.read(1)
                if next1 == '[':
                    next2 = sys.stdin.read(1)
                    if next2 == 'A': key = 'k' # Up
                    elif next2 == 'B': key = 'j' # Down
                    elif next2 == 'C': key = 'l' # Right
                    elif next2 == 'D': key = 'h' # Left
                else: key = '\x1b'
            else:
                # Actual Esc
                self.zoom_node = self.root
                self.scroll_depth = 0
                self.search_query = ""
                self.matches = []
                return True

        if key == 'q' or key == '\x03': return False
        elif key == 'j':
            if self.selected_node.children_list: self.selected_node = self.selected_node.children_list[0]
        elif key == 'k':
            if self.selected_node.parent: self.selected_node = self.selected_node.parent
        elif key == 'h':
            if self.selected_node.parent:
                siblings = self.selected_node.parent.children_list
                idx = siblings.index(self.selected_node); 
                if idx > 0: self.selected_node = siblings[idx - 1]
        elif key == 'l':
            if self.selected_node.parent:
                siblings = self.selected_node.parent.children_list
                idx = siblings.index(self.selected_node)
                if idx < len(siblings) - 1: self.selected_node = siblings[idx + 1]
        elif key == '\r':
            self.zoom_node = self.selected_node
            self.scroll_depth = self.zoom_node.depth
        elif key == '/': self.do_search()
        elif key == '#':
            self.search_query = f"^{re.escape(self.selected_node.name)}$"
            self.update_matches()
        elif key == 'n':
            if self.matches:
                self.match_idx = (self.match_idx + 1) % len(self.matches)
                self.selected_node = self.matches[self.match_idx]
        elif key == 'N':
            if self.matches:
                self.match_idx = (self.match_idx - 1) % len(self.matches)
                self.selected_node = self.matches[self.match_idx]
        elif key == 'f': self.scroll_depth += 1
        elif key == 'b': self.scroll_depth = max(0, self.scroll_depth - 1)
        elif key == 'g': self.scroll_depth = 0
        elif key == 'G':
            max_d = 0
            stack = [self.root]
            while stack:
                curr = stack.pop()
                max_d = max(max_d, curr.depth)
                stack.extend(curr.children_list)
            self.scroll_depth = max(0, max_d - (self.height - 8))
        elif key == 'r':
            self.zoom_node = self.root
            self.selected_node = self.root
            self.scroll_depth = 0
            self.search_query = ""
            self.matches = []
        return True

    def do_search(self):
        termios.tcsetattr(self.fd, termios.TCSADRAIN, self.old_settings)
        sys.stdout.write("\x1b[" + str(self.height) + ";1H\x1b[2K/")
        sys.stdout.flush()
        query = ""
        while True:
            char = sys.stdin.read(1)
            if char == '\r' or char == '\n': break
            if char == '\x1b': query = ""; break
            if char == '\x7f':
                if query:
                    query = query[:-1]
                    sys.stdout.write("\b \b")
                    sys.stdout.flush()
            else:
                query += char
                sys.stdout.write(char)
                sys.stdout.flush()
        tty.setraw(self.fd)
        if query:
            self.search_query = query
            self.update_matches()

